"""R-ENGINE-02 (track A of the own 3D try-on engine): the GARMENT DATA SPEC, its validator and two sample garments generated by this code.

A garment = one .glb (a single mesh whose materials are named ``base`` (required) and optionally ``trim``) + a size-chart JSON (``garment.v1``).
The .glb is the REFERENCE size only; the chart lists the measurements of every size (a table, not extra meshes). Nothing here fits a garment to a body (that is R-ENGINE-03)
and nothing here is a photo: the samples are plain tubes around the stylised base body, so they are for tests and previews, not realistic clothes.
Rights: a garment that uses a third-party asset must say so and carry ``rights_confirmed: true`` — a chart that claims a third-party asset without it is refused.
"""
from __future__ import annotations

import math
import re
import struct
from typing import Any

from app import base_models
from app.glb_tools import GlbError, build_glb, inspect_glb, parse_glb

SCHEMA = "garment.v1"
KINDS = ("top", "bottom")
MAX_SIZES = 8
MAX_TRIANGLES = 50_000
MATERIALS_ALLOWED = ("base", "trim")
REQUIRED_MEASURES = {"top": ("chest_cm", "waist_cm", "length_cm"), "bottom": ("waist_cm", "hips_cm", "length_cm")}
OPTIONAL_MEASURES = {"top": ("sleeve_cm",), "bottom": ()}
MEASURE_RANGE = (20.0, 250.0)          # cm, provisional sanity range
ID_RE = re.compile(r"^[a-z0-9][a-z0-9_-]{1,47}$")
SIZE_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9 ._-]{0,11}$")


class GarmentError(ValueError):
    """Carries every problem found, not just the first."""

    def __init__(self, problems: list[str]) -> None:
        super().__init__("; ".join(problems))
        self.problems = problems


def validate_spec(spec: Any) -> None:
    problems: list[str] = []
    if not isinstance(spec, dict):
        raise GarmentError(["spec must be an object"])
    if spec.get("schema") != SCHEMA:
        problems.append(f"schema must be {SCHEMA!r}")
    if not (isinstance(spec.get("id"), str) and ID_RE.match(spec["id"])):
        problems.append("id must be 2-48 chars of a-z 0-9 _ - starting with a letter or digit")
    kind = spec.get("kind")
    if kind not in KINDS:
        problems.append(f"kind must be one of {list(KINDS)}")
    sizes = spec.get("sizes")
    if not isinstance(sizes, dict) or not 1 <= len(sizes) <= MAX_SIZES:
        problems.append(f"sizes must be an object with 1 to {MAX_SIZES} entries")
        sizes = {}
    for label, chart in sizes.items():
        if not (isinstance(label, str) and SIZE_RE.match(label)):
            problems.append(f"size label {label!r} is not allowed")
            continue
        if not isinstance(chart, dict):
            problems.append(f"size {label}: must be an object of measurements")
            continue
        required = REQUIRED_MEASURES.get(kind, ())
        allowed = set(required) | set(OPTIONAL_MEASURES.get(kind, ()))
        for key in required:
            if key not in chart:
                problems.append(f"size {label}: missing {key}")
        for key, value in chart.items():
            if key not in allowed:
                problems.append(f"size {label}: unknown measurement {key!r}")
            elif isinstance(value, bool) or not isinstance(value, (int, float)) or not MEASURE_RANGE[0] <= float(value) <= MEASURE_RANGE[1]:
                problems.append(f"size {label}: {key} must be a number from {MEASURE_RANGE[0]:g} to {MEASURE_RANGE[1]:g}")
    ref = spec.get("reference_size")
    if ref not in sizes:
        problems.append("reference_size must be one of the sizes")
    source = spec.get("source")
    if not isinstance(source, dict):
        problems.append("source must be an object")
    else:
        if not (isinstance(source.get("provenance"), str) and source["provenance"].strip()):
            problems.append("source.provenance must say where the garment came from")
        third = source.get("third_party_asset")
        if not isinstance(third, bool):
            problems.append("source.third_party_asset must be true or false")
        elif third and source.get("rights_confirmed") is not True:
            problems.append("a third-party asset needs source.rights_confirmed = true")
    if problems:
        raise GarmentError(problems)


def validate_glb(data: bytes) -> dict[str, Any]:
    try:
        doc, _ = parse_glb(data)
        info = inspect_glb(data)
    except GlbError as exc:
        raise GarmentError([f"glb: {exc}"]) from exc
    problems: list[str] = []
    if len(doc.get("meshes", [])) != 1:
        problems.append("glb must contain exactly one mesh")
    names = [m.get("name") for m in doc.get("materials", [])]
    if "base" not in names:
        problems.append("glb needs a material named 'base'")
    extra = [n for n in names if n not in MATERIALS_ALLOWED]
    if extra:
        problems.append(f"unknown material names {extra}")
    if info["triangles"] > MAX_TRIANGLES:
        problems.append(f"too many triangles ({info['triangles']} > {MAX_TRIANGLES})")
    if problems:
        raise GarmentError(problems)
    return info


def validate_garment(glb: bytes, spec: Any) -> dict[str, Any]:
    """Both parts, every problem reported. Also checks that the reference-size chart agrees with the mesh height (within 2 cm)."""
    problems: list[str] = []
    info: dict[str, Any] = {}
    for check in (lambda: validate_spec(spec), lambda: info.update(validate_glb(glb))):
        try:
            check()
        except GarmentError as exc:
            problems += exc.problems
    if not problems:
        ref = spec["sizes"][spec["reference_size"]]
        height_cm = info["size"][1] * 100
        if abs(height_cm - ref["length_cm"]) > 2.0:
            problems.append(f"reference size length_cm {ref['length_cm']} does not match the mesh height {height_cm:.1f} cm")
    if problems:
        raise GarmentError(problems)
    return {"triangles": info["triangles"], "size_m": info["size"], "kind": spec["kind"], "sizes": sorted(spec["sizes"])}


# ---- sample garments (plain tubes around the stylised base body) -------------------------------------------------------------------------------------------------

def _ring_cm(a: float, b: float) -> float:
    return round(base_models._perimeter_cm(a, b), 1)


def _write(mesh: base_models._Mesh, kind: str, colour: tuple[int, int, int]) -> bytes:
    xs, ys, zs = mesh.pos[0::3], mesh.pos[1::3], mesh.pos[2::3]
    binary = struct.pack(f"<{len(mesh.pos)}f", *mesh.pos)
    binary += b"\x00" * (-len(binary) % 4)
    idx_off = len(binary)
    binary += struct.pack(f"<{len(mesh.idx)}H", *mesh.idx)
    doc = {"asset": {"version": "2.0", "generator": "ai-creator-studio garments"}, "scene": 0, "scenes": [{"nodes": [0]}],
           "nodes": [{"name": f"sample_{kind}", "mesh": 0, "extras": {"generated_by_code": True, "garment_schema": SCHEMA, "kind": kind,
                                                                      "licence": "generated by this repository's code; no third-party asset"}}],
           "meshes": [{"name": f"sample_{kind}", "primitives": [{"attributes": {"POSITION": 0}, "indices": 1, "material": 0}]}],
           "materials": [{"name": "base", "doubleSided": True, "pbrMetallicRoughness": {"baseColorFactor": [c / 255 for c in colour] + [1.0], "metallicFactor": 0.0, "roughnessFactor": 0.9}}],
           "accessors": [{"bufferView": 0, "componentType": 5126, "count": len(mesh.pos) // 3, "type": "VEC3", "min": [min(xs), min(ys), min(zs)], "max": [max(xs), max(ys), max(zs)]},
                         {"bufferView": 1, "componentType": 5123, "count": len(mesh.idx), "type": "SCALAR"}],
           "bufferViews": [{"buffer": 0, "byteOffset": 0, "byteLength": len(mesh.pos) * 4}, {"buffer": 0, "byteOffset": idx_off, "byteLength": len(mesh.idx) * 2}],
           "buffers": [{"byteLength": len(binary)}]}
    return build_glb(doc, binary)


def build_sample_garment(kind: str, sex: str = "male", ease_cm: float = 4.0, colour: tuple[int, int, int] = (60, 90, 160)) -> tuple[bytes, dict[str, Any]]:
    """A plain t-shirt body or trousers tube around the preset body of ``sex`` with ``ease_cm`` of room, plus its garment.v1 spec (sizes S/M/L = reference -4/0/+4 cm, a TABLE only)."""
    if kind not in KINDS or sex not in base_models.SEXES:
        raise ValueError("unknown kind or sex preset")
    if isinstance(ease_cm, bool) or not isinstance(ease_cm, (int, float)) or not 0.0 <= float(ease_cm) <= 20.0:
        raise ValueError("ease_cm must be a number from 0 to 20")
    p = base_models.PRESETS[sex]
    h = p["height"]
    off = float(ease_cm) / 100.0 / (2 * math.pi)     # radial offset giving about ease_cm more perimeter
    mesh = base_models._Mesh()
    hip_y, waist_y, chest_y, shoulder_y = 0.52 * h, 0.60 * h, 0.70 * h, 0.81 * h

    def ring(centre_x: float, y: float, a: float, b: float) -> tuple[tuple[float, float, float], float, float]:
        return ((centre_x, y, 0.0), a + off, b + off)
    if kind == "top":
        hem_y = hip_y
        stops = [ring(0, hem_y, p["hip"][0], p["hip"][1]), ring(0, waist_y, *p["waist"]), ring(0, chest_y, *p["chest"]), ring(0, shoulder_y, p["shoulder"] * 0.72, p["chest"][1] * 0.92)]
        mesh.tube(stops)
        length_cm = round((shoulder_y - hem_y) * 100, 1)
        measures = {"chest_cm": _ring_cm(stops[2][1], stops[2][2]), "waist_cm": _ring_cm(stops[1][1], stops[1][2]), "length_cm": length_cm}
    else:
        leg_x = p["hip"][0] * 0.55
        ankle_y = 0.04 * h
        stops_torso = [ring(0, hip_y, *p["hip"]), ring(0, waist_y, *p["waist"])]
        mesh.tube(stops_torso)
        for side in (-1, 1):
            mesh.tube([ring(side * leg_x, hip_y, p["thigh"], p["thigh"]), ring(side * leg_x * 0.95, 0.28 * h, p["thigh"] * 0.72, p["thigh"] * 0.72), ring(side * leg_x * 0.9, ankle_y, p["calf"] * 0.65, p["calf"] * 0.65)])
        length_cm = round((waist_y - ankle_y) * 100, 1)
        measures = {"waist_cm": _ring_cm(stops_torso[1][1], stops_torso[1][2]), "hips_cm": _ring_cm(stops_torso[0][1], stops_torso[0][2]), "length_cm": length_cm}
    glb = _write(mesh, kind, colour)
    # the chart's length_cm is the height the mesh really has (a bottom runs from the waist down to the ankles), so chart and mesh cannot disagree
    real_cm = round(inspect_glb(glb)["size"][1] * 100, 1)
    measures["length_cm"] = real_cm
    chart = {"M": dict(measures)}
    for label, delta in (("S", -4.0), ("L", 4.0)):
        chart[label] = {key: (round(value + delta, 1) if key != "length_cm" else value) for key, value in measures.items()}
    spec = {"schema": SCHEMA, "id": f"sample-{kind}-{sex}", "kind": kind, "reference_size": "M", "sizes": chart,
            "source": {"provenance": "generated by this repository's code (app/garments.py build_sample_garment)", "third_party_asset": False, "rights_confirmed": True}}
    return glb, spec
